import{_ as a,o as i,c as l,a3 as r}from"./chunks/framework.Bh_aNVBG.js";const o="/images/super-admin/image-27.png",d="/images/super-admin/image-28.png",e="/images/super-admin/image-29.png",n="/images/super-admin/image-30.png",s="/images/super-admin/image-31.png",p="/images/super-admin/image-32.png",h="/images/super-admin/%EC%A0%84%EC%B2%B4_%EC%9D%BC%EC%A0%95_%ED%99%94%EB%A9%B4.png",g="/images/super-admin/image-33.png",m="/images/super-admin/image-34.png",c="/images/super-admin/image-35.png",b="/images/super-admin/image-36.png",_="/images/super-admin/image-37.png",u="/images/super-admin/image-38.png",q="/images/super-admin/image-39.png",k="/images/super-admin/image-40.png",A=JSON.parse('{"title":"5. 행사 콘텐츠 등록 및 관리","description":"","frontmatter":{},"headers":[],"relativePath":"contents.md","filePath":"contents.md"}'),x={name:"contents.md"};function f(P,t,y,C,E,S){return i(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="_5-행사-콘텐츠-등록-및-관리" tabindex="-1">5. 행사 콘텐츠 등록 및 관리 <a class="header-anchor" href="#_5-행사-콘텐츠-등록-및-관리" aria-label="Permalink to &quot;5. 행사 콘텐츠 등록 및 관리&quot;">​</a></h1><p>인포디오에서는 축제 및 행사와 관련된 다양한 정보를 콘텐츠로 등록하여 방문객에게 제공할 수 있습니다.</p><p>프로젝트 운영자는 CMS에서 행사 소개, 프로그램 안내, 행사 일정, 공지사항 등을 직접 등록하고 관리할 수 있습니다.</p><p>등록한 콘텐츠는 서비스 구성에 따라 방문객용 안내 페이지에서 제공되며, 행사 운영 중에도 내용을 수정할 수 있습니다.</p><h2 id="_5-1-콘텐츠-관리-기능-안내" tabindex="-1">5.1. 콘텐츠 관리 기능 안내 <a class="header-anchor" href="#_5-1-콘텐츠-관리-기능-안내" aria-label="Permalink to &quot;5.1. 콘텐츠 관리 기능 안내&quot;">​</a></h2><p>CMS에서 제공하는 주요 콘텐츠 관리 기능은 다음과 같습니다.</p><table tabindex="0"><thead><tr><th>관리 기능</th><th>설명</th></tr></thead><tbody><tr><td>상세 콘텐츠</td><td>행사 및 프로그램의 상세 정보, 이미지, 안내 문구 등을 등록하고 관리</td></tr><tr><td>일정</td><td>공연, 체험, 전시 등 행사 프로그램의 일정 관리</td></tr><tr><td>일정 카테고리</td><td>일정의 유형을 구분하는 카테고리 관리</td></tr><tr><td>일정 배지</td><td>일정에 표시할 강조 문구 및 배지 관리</td></tr><tr><td>공지사항</td><td>방문객에게 전달할 주요 공지사항 관리</td></tr></tbody></table><h3 id="콘텐츠-등록-권장-순서" tabindex="-1">콘텐츠 등록 권장 순서 <a class="header-anchor" href="#콘텐츠-등록-권장-순서" aria-label="Permalink to &quot;콘텐츠 등록 권장 순서&quot;">​</a></h3><ol><li>일정 카테고리 및 배지 설정</li><li>상세 콘텐츠 등록</li><li>행사 일정 등록 및 상세 콘텐츠 연결</li><li>공지사항 등록</li><li>방문객용 안내 페이지에서 표시 상태 확인</li></ol><hr><h2 id="_5-2-상세-콘텐츠-등록-및-관리" tabindex="-1">5.2. 상세 콘텐츠 등록 및 관리 <a class="header-anchor" href="#_5-2-상세-콘텐츠-등록-및-관리" aria-label="Permalink to &quot;5.2. 상세 콘텐츠 등록 및 관리&quot;">​</a></h2><p>상세 콘텐츠는 방문객에게 행사, 프로그램, 시설 등의 정보를 자세하게 안내하기 위한 기능입니다.</p><p>제목, 설명, 이미지, 주요 정보, 상세 일정 등을 등록하여 하나의 안내 페이지로 구성할 수 있습니다.</p><p>예를 들어 공연 소개, 체험 프로그램 안내, 부스 이용 안내 등에 활용할 수 있습니다.</p><h3 id="_1-상세-콘텐츠-관리-화면-이동" tabindex="-1">① 상세 콘텐츠 관리 화면 이동 <a class="header-anchor" href="#_1-상세-콘텐츠-관리-화면-이동" aria-label="Permalink to &quot;① 상세 콘텐츠 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>상세 콘텐츠</strong> 메뉴를 선택합니다.</li><li>등록된 콘텐츠 목록을 확인합니다.</li><li>신규 콘텐츠를 등록하려면 콘텐츠 추가 화면으로 이동합니다.</li></ol><p><img src="'+o+'" alt="image.png"></p><h3 id="_2-기본-정보-입력" tabindex="-1">② 기본 정보 입력 <a class="header-anchor" href="#_2-기본-정보-입력" aria-label="Permalink to &quot;② 기본 정보 입력&quot;">​</a></h3><p>상세 콘텐츠의 기본 정보를 입력합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>제목</td><td>상세 콘텐츠의 이름</td></tr><tr><td>URL</td><td>콘텐츠에 부여된 개별 접근 주소</td></tr><tr><td>부제</td><td>제목 아래 표시할 보조 문구</td></tr><tr><td>설명</td><td>방문객에게 제공할 콘텐츠 소개 문구</td></tr></tbody></table><p><strong>등록 방법</strong></p><ol><li>상세 콘텐츠 추가 화면으로 이동합니다.</li><li><strong>제목</strong>을 입력합니다.</li><li>필요한 경우 <strong>부제</strong>를 입력합니다.</li><li><strong>설명</strong>에 콘텐츠의 주요 내용을 작성합니다.</li><li>다른 콘텐츠 구성 항목을 설정합니다.</li></ol><p><img src="'+d+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>제목은 방문객이 콘텐츠의 내용을 쉽게 이해할 수 있도록 작성하는 것이 좋습니다.</p><p>예를 들어 &#39;프로그램 01&#39;보다는 &#39;전통 공예 체험 프로그램&#39;처럼 구체적인 명칭을 사용하는 것을 권장합니다.</p></blockquote><h3 id="_3-배너-이미지-및-미디어-설정" tabindex="-1">③ 배너 이미지 및 미디어 설정 <a class="header-anchor" href="#_3-배너-이미지-및-미디어-설정" aria-label="Permalink to &quot;③ 배너 이미지 및 미디어 설정&quot;">​</a></h3><p>상세 콘텐츠 상단에 표시할 이미지나 영상 콘텐츠를 등록합니다.</p><p>배너 영역은 상세 콘텐츠의 주요 시각 자료를 보여주는 영역입니다.</p><p><strong>설정 방법</strong></p><ol><li><strong>배너 영역</strong>으로 이동합니다.</li><li>등록할 미디어 유형을 선택합니다.</li><li>이미지 또는 영상 관련 정보를 등록합니다.</li><li>추가된 미디어를 확인합니다.</li></ol><p><img src="'+e+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>배너 영역은 상세 콘텐츠의 주요 정보를 전달하는 필수 구성 영역입니다.</p><p>이미지는 내용에 적합하고 해상도가 충분한 파일을 사용하는 것을 권장합니다.</p></blockquote><h3 id="_4-주요-정보-등록" tabindex="-1">④ 주요 정보 등록 <a class="header-anchor" href="#_4-주요-정보-등록" aria-label="Permalink to &quot;④ 주요 정보 등록&quot;">​</a></h3><p>주요 정보 영역에서는 콘텐츠와 관련된 정보를 항목별로 등록할 수 있습니다.</p><p>예를 들어 운영 시간, 이용 요금, 문의처 등 방문객이 알아야 할 정보를 구성할 수 있습니다.</p><table tabindex="0"><thead><tr><th>항목명 예시</th><th>내용 예시</th></tr></thead><tbody><tr><td>운영 시간</td><td>10:00 ~ 18:00</td></tr><tr><td>이용 요금</td><td>무료</td></tr><tr><td>참여 대상</td><td>누구나 참여 가능</td></tr><tr><td>문의</td><td>현장 안내소</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li><strong>주요 정보</strong> 영역으로 이동합니다.</li><li><strong>항목 추가</strong> 버튼을 클릭합니다.</li><li>항목명과 내용을 입력합니다.</li><li>필요한 만큼 항목을 추가합니다.</li><li>불필요한 항목은 삭제합니다.</li></ol><p><img src="'+n+'" alt="image.png"></p><h3 id="_5-상세-일정-등록" tabindex="-1">⑤ 상세 일정 등록 <a class="header-anchor" href="#_5-상세-일정-등록" aria-label="Permalink to &quot;⑤ 상세 일정 등록&quot;">​</a></h3><p>상세 콘텐츠에 관련된 일정이 있다면 <strong>상세 일정</strong>을 추가할 수 있습니다.</p><p>예를 들어 하나의 공연 프로그램에 여러 회차의 공연 시간이 있다면 회차별 일정을 구성할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>상세 콘텐츠 편집 화면에서 <strong>상세 일정</strong> 영역으로 이동합니다.</li><li><strong>상세 일정 추가</strong> 버튼을 클릭합니다.</li><li>일정 정보를 입력합니다.</li><li>일정 등록을 완료합니다.</li><li>상세 일정 목록에 추가된 내용을 확인합니다.</li></ol><p><img src="'+s+'" alt="image.png"></p><h3 id="_6-하단-액션-버튼-설정" tabindex="-1">⑥ 하단 액션 버튼 설정 <a class="header-anchor" href="#_6-하단-액션-버튼-설정" aria-label="Permalink to &quot;⑥  하단 액션 버튼 설정&quot;">​</a></h3><p>상세 콘텐츠 하단에 별도의 이동 버튼을 표시할 수 있습니다.</p><p>이 버튼은 방문객을 외부 사이트나 관련 페이지로 이동시키는 용도로 사용할 수 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>공개</td><td>하단 버튼 표시 여부</td></tr><tr><td>버튼 텍스트</td><td>버튼에 표시할 문구</td></tr><tr><td>연결 링크</td><td>버튼 클릭 시 이동할 주소 또는 페이지</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li><strong>하단 액션 버튼</strong> 영역으로 이동합니다.</li><li>버튼 공개 여부를 설정합니다.</li><li>버튼 텍스트를 입력합니다.</li><li>이동할 링크를 설정합니다.</li><li>변경 내용을 저장합니다.</li></ol><p><img src="'+p+'" alt="image.png"></p><h3 id="_7-상세-콘텐츠-수정-및-삭제" tabindex="-1">⑦ 상세 콘텐츠 수정 및 삭제 <a class="header-anchor" href="#_7-상세-콘텐츠-수정-및-삭제" aria-label="Permalink to &quot;⑦ 상세 콘텐츠 수정 및 삭제&quot;">​</a></h3><p>등록된 상세 콘텐츠는 목록에서 선택하여 내용을 수정할 수 있습니다.</p><p><strong>수정 방법</strong></p><ol><li>상세 콘텐츠 목록에서 수정할 콘텐츠를 선택합니다.</li><li>변경할 정보를 수정합니다.</li><li>저장 버튼을 클릭합니다.</li></ol><p>콘텐츠 삭제가 필요한 경우에는 삭제 기능을 이용합니다.</p><blockquote><p><strong>주의사항</strong></p><p>상세 콘텐츠가 일정이나 지도 등 다른 기능과 연결되어 있다면 삭제 시 연결된 화면에 영향을 줄 수 있습니다.</p><p>삭제 전 콘텐츠의 사용 여부를 확인해 주세요.</p></blockquote><h2 id="_5-3-행사-일정-등록-및-관리" tabindex="-1">5.3. 행사 일정 등록 및 관리 <a class="header-anchor" href="#_5-3-행사-일정-등록-및-관리" aria-label="Permalink to &quot;5.3. 행사 일정 등록 및 관리&quot;">​</a></h2><p>일정 관리 기능은 공연, 전시, 체험 프로그램 등 축제에서 진행되는 다양한 행사의 날짜와 시간을 등록하고 관리하는 기능입니다.</p><p>등록된 일정은 방문객용 안내 페이지의 일정 화면에 표시되며, 일정별 카테고리, 배지, 장소 및 관련 콘텐츠를 설정할 수 있습니다.</p><h3 id="_1-일정-관리-화면-이동" tabindex="-1">① 일정 관리 화면 이동 <a class="header-anchor" href="#_1-일정-관리-화면-이동" aria-label="Permalink to &quot;① 일정 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>전체</strong> <strong>일정</strong> 메뉴를 선택합니다.</li><li>일정 관리 화면에서 등록된 일정을 확인합니다.</li><li>새로운 일정을 등록하려면 <strong>일정 추가</strong> 기능을 선택합니다.</li></ol><p><img src="'+h+'" alt="전체 일정 화면.png"></p><h3 id="_2-신규-일정-등록" tabindex="-1">② 신규 일정 등록 <a class="header-anchor" href="#_2-신규-일정-등록" aria-label="Permalink to &quot;② 신규 일정 등록&quot;">​</a></h3><p><strong>일정 추가</strong> 화면에서는 다음 정보를 입력할 수 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>이름</td><td>방문객에게 표시할 일정 또는 프로그램 이름</td></tr><tr><td>시작일 및 시간</td><td>일정이 시작되는 날짜와 시간</td></tr><tr><td>종료일 및 시간</td><td>일정이 종료되는 날짜와 시간</td></tr><tr><td>종일/상시</td><td>특정 시간에 제한되지 않는 일정 설정</td></tr><tr><td>기간 내 반복</td><td>설정한 기간 동안 지정된 시간에 반복되는 일정</td></tr><tr><td>이미지</td><td>일정에 표시할 대표 이미지</td></tr><tr><td>장소</td><td>프로그램이 진행되는 장소</td></tr><tr><td>카테고리</td><td>일정의 유형을 구분하는 분류</td></tr><tr><td>배지</td><td>일정에 표시할 강조 표시</td></tr><tr><td>관련 콘텐츠</td><td>일정과 연결할 상세 콘텐츠</td></tr></tbody></table><p><strong>등록 방법</strong></p><ol><li><strong>일정 추가</strong> 버튼을 클릭합니다.</li><li>일정 이름을 입력합니다.</li><li>시작일과 종료일을 설정합니다.</li><li>필요한 경우 종일/상시 또는 기간 내 반복을 설정합니다.</li><li>이미지와 장소를 등록합니다.</li><li>카테고리 및 배지를 선택합니다.</li><li>연결할 상세 콘텐츠가 있다면 선택합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><img src="'+g+'" alt="image.png"></p><h3 id="_3-종일-상시-일정-설정" tabindex="-1">③ 종일/상시 일정 설정 <a class="header-anchor" href="#_3-종일-상시-일정-설정" aria-label="Permalink to &quot;③ 종일/상시 일정 설정&quot;">​</a></h3><p>특정 시간 없이 운영되는 행사나 프로그램은 <strong>종일/상시</strong> 옵션을 이용하여 설정할 수 있습니다.</p><p>예를 들어 행사 기간 동안 계속 운영되는 전시, 체험 공간 등에 활용할 수 있습니다.</p><h3 id="_4-기간-내-반복-일정-설정" tabindex="-1">④ 기간 내 반복 일정 설정 <a class="header-anchor" href="#_4-기간-내-반복-일정-설정" aria-label="Permalink to &quot;④ 기간 내 반복 일정 설정&quot;">​</a></h3><p>일정이 여러 날짜에 걸쳐 동일한 시간에 반복되는 경우 <strong>기간 내 반복</strong> 기능을 사용할 수 있습니다.</p><p>예를 들어 10월 15일부터 10월 17일까지 매일 14:00~15:00에 진행되는 프로그램을 등록할 수 있습니다.</p><table tabindex="0"><thead><tr><th>설정 항목</th><th>입력 예시</th></tr></thead><tbody><tr><td>시작일</td><td>2026-10-15</td></tr><tr><td>종료일</td><td>2026-10-17</td></tr><tr><td>시작 시간</td><td>14:00</td></tr><tr><td>종료 시간</td><td>15:00</td></tr><tr><td>기간 내 반복</td><td>활성화</td></tr></tbody></table><p>위와 같이 설정하면 지정한 기간 동안 매일 동일한 시간에 진행되는 일정으로 구성할 수 있습니다.</p><p><img src="'+m+'" alt="image.png"></p><h3 id="_5-상세-콘텐츠-연결" tabindex="-1">⑤ 상세 콘텐츠 연결 <a class="header-anchor" href="#_5-상세-콘텐츠-연결" aria-label="Permalink to &quot;⑤ 상세 콘텐츠 연결&quot;">​</a></h3><p>일정에는 기존에 등록한 상세 콘텐츠를 연결할 수 있습니다.</p><p>이를 통해 방문객이 일정 정보를 확인한 후 관련 프로그램의 상세 안내를 확인할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>일정 추가 또는 편집 화면에서 <strong>관련 콘텐츠</strong> 항목으로 이동합니다.</li><li>연결할 상세 콘텐츠를 검색합니다.</li><li>원하는 콘텐츠를 선택합니다.</li><li>설정을 저장합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>연결할 상세 콘텐츠가 없다면 먼저 상세 콘텐츠를 등록한 후 일정을 설정하는 것이 편리합니다.</p></blockquote><h3 id="_6-일정-수정-및-삭제" tabindex="-1">⑥ 일정 수정 및 삭제 <a class="header-anchor" href="#_6-일정-수정-및-삭제" aria-label="Permalink to &quot;⑥ 일정 수정 및 삭제&quot;">​</a></h3><p><strong>일정 수정</strong></p><ol><li>일정 관리 화면에서 변경할 일정을 선택합니다.</li><li>일정 편집 화면에서 필요한 정보를 수정합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><strong>일정 삭제</strong></p><ol><li>일정 관리 화면에서 삭제할 일정을 찾습니다.</li><li>삭제 기능을 선택합니다.</li><li>삭제할 일정 정보를 확인합니다.</li><li>삭제를 진행합니다.</li></ol><hr><h2 id="_5-4-일정-카테고리-및-배지-관리" tabindex="-1">5.4. 일정 카테고리 및 배지 관리 <a class="header-anchor" href="#_5-4-일정-카테고리-및-배지-관리" aria-label="Permalink to &quot;5.4. 일정 카테고리 및 배지 관리&quot;">​</a></h2><p>일정 카테고리와 배지는 방문객이 다양한 행사 일정을 쉽게 구분할 수 있도록 지원하는 기능입니다.</p><p>카테고리는 일정의 유형을 분류하는 데 사용되며, 배지는 특정 일정의 특징이나 중요 정보를 강조하는 데 사용됩니다.</p><h3 id="_1-일정-카테고리-관리" tabindex="-1">① 일정 카테고리 관리 <a class="header-anchor" href="#_1-일정-카테고리-관리" aria-label="Permalink to &quot;① 일정 카테고리 관리&quot;">​</a></h3><p>일정 카테고리는 방문객용 일정 화면 상단의 탭 메뉴에 표시됩니다.</p><p>예를 들어 공연, 체험, 전시 등으로 일정을 분류할 수 있습니다.</p><p><strong>카테고리 등록 방법</strong></p><ol><li>프로젝트 관리 화면에서 <strong>일정 카테고리/배지</strong> 메뉴로 이동합니다.</li><li>카테고리 관리 영역을 확인합니다.</li><li>카테고리 이름을 입력합니다.</li><li><strong>추가</strong> 버튼을 클릭합니다.</li><li>필요한 카테고리를 모두 등록합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><img src="'+c+'" alt="image.png"></p><p><strong>카테고리 구성 예시</strong></p><table tabindex="0"><thead><tr><th>카테고리</th><th>해당 프로그램 예시</th></tr></thead><tbody><tr><td>공연</td><td>개막식, 버스킹, 특별 공연</td></tr><tr><td>체험</td><td>공예 체험, 참여 프로그램</td></tr><tr><td>전시</td><td>미술 전시, 특별 전시</td></tr><tr><td>기타</td><td>부대 행사 및 기타 프로그램</td></tr></tbody></table><p>등록한 카테고리는 드래그하여 표시 순서를 변경할 수 있습니다.</p><blockquote><p><strong>주의사항</strong></p><p>카테고리를 삭제하면 해당 카테고리로 분류되었던 일정은 미분류 상태로 변경될 수 있습니다.</p><p>카테고리를 삭제하기 전 관련 일정을 확인해 주세요.</p></blockquote><h3 id="_2-일정-배지-관리" tabindex="-1">② 일정 배지 관리 <a class="header-anchor" href="#_2-일정-배지-관리" aria-label="Permalink to &quot;② 일정 배지 관리&quot;">​</a></h3><p>일정 배지는 행사 일정에 특정 특징을 표시할 때 사용하는 기능입니다.</p><p>예를 들어 &#39;무료&#39;, &#39;인기&#39;, &#39;사전예약&#39; 등의 배지를 만들어 활용할 수 있습니다.</p><p><strong>배지 등록 방법</strong></p><ol><li><strong>일정 카테고리/배지</strong> 메뉴에서 배지 관리 영역으로 이동합니다.</li><li>배지 이름을 입력합니다.</li><li><strong>추가</strong> 버튼을 클릭합니다.</li><li>필요한 배지를 추가합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><img src="'+b+'" alt="image.png"></p><p><strong>배지 활용 예시</strong></p><table tabindex="0"><thead><tr><th>배지</th><th>활용 목적</th></tr></thead><tbody><tr><td>무료</td><td>무료 참여 프로그램 안내</td></tr><tr><td>인기</td><td>주요 인기 프로그램 강조</td></tr><tr><td>사전예약</td><td>예약이 필요한 프로그램 안내</td></tr><tr><td>현장접수</td><td>현장에서 신청하는 프로그램 안내</td></tr></tbody></table><p>배지를 등록한 후 일정 편집 화면에서 해당 배지를 선택하여 적용할 수 있습니다.</p><hr><h2 id="_5-5-공지사항-등록-및-관리" tabindex="-1">5.5. 공지사항 등록 및 관리 <a class="header-anchor" href="#_5-5-공지사항-등록-및-관리" aria-label="Permalink to &quot;5.5. 공지사항 등록 및 관리&quot;">​</a></h2><p>공지사항은 행사 운영과 관련된 중요한 정보를 방문객에게 전달하기 위한 기능입니다.</p><p>행사 시간 변경, 운영 안내, 긴급 공지 등 방문객에게 안내해야 하는 정보를 등록할 수 있습니다.</p><h3 id="_1-공지사항-관리-화면-이동" tabindex="-1">① 공지사항 관리 화면 이동 <a class="header-anchor" href="#_1-공지사항-관리-화면-이동" aria-label="Permalink to &quot;① 공지사항 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>공지사항</strong> 메뉴를 선택합니다.</li><li>현재 등록된 공지사항 목록을 확인합니다.</li><li>필요한 경우 새로운 공지사항을 등록합니다.</li></ol><p><img src="'+_+'" alt="image.png"></p><h3 id="_2-공지사항-등록" tabindex="-1">② 공지사항 등록 <a class="header-anchor" href="#_2-공지사항-등록" aria-label="Permalink to &quot;② 공지사항 등록&quot;">​</a></h3><p><strong>등록 방법</strong></p><ol><li>공지사항 입력 영역에 안내할 내용을 입력합니다.</li><li>작성한 문구를 확인합니다.</li><li><strong>추가</strong> 버튼을 클릭합니다.</li><li>등록된 공지사항을 확인합니다.</li></ol><p><strong>공지사항 작성 예시</strong></p><table tabindex="0"><thead><tr><th>상황</th><th>공지사항 예시</th></tr></thead><tbody><tr><td>행사 시간 변경</td><td>우천으로 인해 야외 공연 시작 시간이 오후 3시로 변경되었습니다.</td></tr><tr><td>운영 안내</td><td>행사장 입장 시 현장 안내요원의 안내에 따라 이동해 주세요.</td></tr><tr><td>시설 안내</td><td>행사장 내 임시 화장실은 중앙 안내소 오른쪽에 마련되어 있습니다.</td></tr><tr><td>교통 안내</td><td>행사장 주변 교통 혼잡이 예상되오니 가급적 대중교통을 이용해 주세요.</td></tr></tbody></table><h3 id="_3-공지사항-노출-순서-변경" tabindex="-1">③ 공지사항 노출 순서 변경 <a class="header-anchor" href="#_3-공지사항-노출-순서-변경" aria-label="Permalink to &quot;③ 공지사항 노출 순서 변경&quot;">​</a></h3><p>등록된 공지사항은 노출 순서를 변경할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>공지사항 목록에서 순서를 변경할 항목을 확인합니다.</li><li>순서 변경 영역을 드래그합니다.</li><li>원하는 위치로 이동합니다.</li><li>변경된 순서를 확인합니다.</li></ol><h3 id="_4-공지사항-노출-및-이력-관리" tabindex="-1">④ 공지사항 노출 및 이력 관리 <a class="header-anchor" href="#_4-공지사항-노출-및-이력-관리" aria-label="Permalink to &quot;④ 공지사항 노출 및 이력 관리&quot;">​</a></h3><p>등록된 공지사항은 <strong>현재 노출 중인 공지사항</strong>과 <strong>노출이 종료된 공지사항</strong>으로 구분하여 관리할 수 있습니다.</p><p>노출이 종료된 공지사항은 완전히 삭제되지 않고 이력에 보관되므로, 필요한 경우 다시 노출할 수 있습니다.</p><p><strong>공지사항 노출 종료 방법</strong></p><ol><li><strong>공지사항</strong> 관리 화면으로 이동합니다.</li><li>현재 노출 중인 공지사항 목록을 확인합니다.</li><li>노출을 종료할 공지사항을 선택합니다.</li><li>노출 종료 기능을 실행합니다.</li><li>해당 공지사항이 이력 목록으로 이동했는지 확인합니다.</li></ol><p><strong>종료된 공지사항 다시 노출하기</strong></p><ol><li>공지사항 관리 화면에서 <strong>이력 목록</strong>을 확인합니다.</li><li>다시 노출할 공지사항을 찾습니다.</li><li>재노출 기능을 실행합니다.</li><li>해당 공지사항이 현재 노출 목록에 추가되었는지 확인합니다.</li><li>필요한 경우 공지사항의 노출 순서를 조정합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>공지사항의 노출을 종료하더라도 기존 내용은 이력에 보관됩니다.</p><p>행사 운영 중 반복적으로 사용하는 안내문은 이력에서 다시 노출하여 활용할 수 있습니다.</p></blockquote><blockquote><p><strong>주의사항</strong></p><p>종료된 공지사항을 다시 노출할 때는 안내 내용이 현재 행사 운영 상황과 일치하는지 반드시 확인해 주세요.</p><p>특히 행사 날짜, 운영 시간, 통제 구역 등의 정보가 변경되었을 수 있으므로 재노출 전에 내용을 검토하는 것이 좋습니다.</p></blockquote><hr><h2 id="_5-6-콘텐츠-등록-후-확인" tabindex="-1">5.6. 콘텐츠 등록 후 확인 <a class="header-anchor" href="#_5-6-콘텐츠-등록-후-확인" aria-label="Permalink to &quot;5.6. 콘텐츠 등록 후 확인&quot;">​</a></h2><p>모든 콘텐츠를 등록한 뒤에는 실제 안내 페이지에 정상적으로 반영되었는지 확인해야 합니다.</p><h3 id="_1-상세-콘텐츠-확인" tabindex="-1">① 상세 콘텐츠 확인 <a class="header-anchor" href="#_1-상세-콘텐츠-확인" aria-label="Permalink to &quot;① 상세 콘텐츠 확인&quot;">​</a></h3><ol><li>방문객용 안내 페이지에 접속합니다.</li><li>등록한 상세 콘텐츠를 확인합니다.</li><li>제목, 설명, 이미지 등이 정상적으로 표시되는지 점검합니다.</li><li>연결된 버튼 및 링크의 동작을 확인합니다.</li></ol><h3 id="_2-일정-확인" tabindex="-1">② 일정 확인 <a class="header-anchor" href="#_2-일정-확인" aria-label="Permalink to &quot;② 일정 확인&quot;">​</a></h3><ol><li>방문객용 안내 페이지의 일정 화면으로 이동합니다.</li><li>등록한 일정의 날짜와 시간을 확인합니다.</li><li>카테고리 및 배지가 올바르게 적용되었는지 확인합니다.</li><li>관련 상세 콘텐츠로 정상적으로 이동하는지 확인합니다.</li></ol><h3 id="_3-공지사항-확인" tabindex="-1">③ 공지사항 확인 <a class="header-anchor" href="#_3-공지사항-확인" aria-label="Permalink to &quot;③ 공지사항 확인&quot;">​</a></h3><ol><li>방문객용 안내 페이지에서 공지사항을 확인합니다.</li><li>등록한 문구가 정상적으로 표시되는지 확인합니다.</li><li>중요 공지의 노출 순서가 적절한지 점검합니다.</li></ol><h3 id="_4-최종-점검-항목" tabindex="-1">④ 최종 점검 항목 <a class="header-anchor" href="#_4-최종-점검-항목" aria-label="Permalink to &quot;④ 최종 점검 항목&quot;">​</a></h3><ul><li>상세 콘텐츠의 제목과 설명이 정확한지 확인</li><li>이미지와 영상이 정상적으로 표시되는지 확인</li><li>주요 정보 및 상세 일정이 올바르게 등록되었는지 확인</li><li>일정 시작일과 종료일이 정확한지 확인</li><li>반복 일정이 의도한 날짜와 시간으로 구성되었는지 확인</li><li>일정 카테고리와 배지가 정상적으로 표시되는지 확인</li><li>관련 콘텐츠 연결이 정상적으로 동작하는지 확인</li><li>공지사항의 내용과 노출 순서가 올바른지 확인</li><li>모바일 환경에서 콘텐츠가 정상적으로 표시되는지 확인</li></ul><p><img src="'+u+'" alt="image.png"></p><p><img src="'+q+'" alt="image.png"></p><p><img src="'+k+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>행사 운영 중 일정이나 프로그램 정보가 변경되었다면 CMS에서 수정한 후 실제 방문객용 안내 페이지에도 변경 사항이 반영되었는지 확인해 주세요.</p></blockquote>',152)])])}const T=a(x,[["render",f]]);export{A as __pageData,T as default};
